import json
HIDE={'regimes':[],'spx':['section.notes','#p-month p.cap','p.cap'],
      'downturn':['footer .src','footer h3','footer h4'],
      'etf':['#method','.srcl','.rc .src','.hrc .src','.hdet .src','.srcs','.nav button[data-go="method"]']}
def strip(cur, links):
    css=('<style>.mdnav{background:#0f1d33;color:#e9eef6;font:500 13px/1.2 "IBM Plex Sans","Segoe UI",system-ui,sans-serif;padding:8px max(16px,env(safe-area-inset-right,0px)) 8px max(16px,env(safe-area-inset-left,0px));display:flex;justify-content:space-between;align-items:center;gap:8px 16px;flex-wrap:wrap}'
         '.mdnav a{color:#e9eef6;text-decoration:none}.mdnav a:hover{text-decoration:underline}.mdnav .home{font-weight:700;letter-spacing:.01em}.mdnav .r{display:flex;gap:6px 14px;align-items:center;flex-wrap:wrap}.mdnav nav{display:flex;gap:4px 14px;flex-wrap:wrap}.mdnav nav a{color:#a9b6c9}.mdnav nav a[aria-current]{color:#fff;font-weight:600}'
         '.mdnav a.reg{color:#a9b6c9;font-size:12px;opacity:.85}.mdnav a.chat{color:#e9eef6;font-weight:600;border:1px solid rgba(255,255,255,.35);border-radius:999px;padding:2px 10px;font-size:12px}.mdnav a.chat:hover{background:#e9eef6;color:#0f1d33;text-decoration:none}.mdnav button{all:unset;cursor:pointer;font-size:12px;color:#a9b6c9;border:1px solid rgba(255,255,255,.22);border-radius:999px;padding:2px 9px}.mdnav button[aria-pressed="true"]{color:#0f1d33;background:#e9eef6}.mdnav button:focus-visible,.mdnav a:focus-visible{outline:2px solid #7fb0f2;outline-offset:2px}'
         'body:not(.md-src) .md-src-only{display:none!important}'
         '@media (max-width:560px){.mdnav nav{display:none}}@media print{.mdnav{display:none!important}}</style>')
    items=[('spx','S&amp;P 500 Stock Returns'),('downturn','Downturn Ledger'),('etf','ETF Allocation Outlook')]
    nav=''.join('<a href="%s"%s>%s</a>'%(links[k],' aria-current="page"' if k==cur else '',n) for k,n in items)
    js=('<script>(function(){var SEL=%s,on=false;try{on=localStorage.getItem("md-src")==="1"}catch(e){}'
        'function tag(){SEL.forEach(function(q){document.querySelectorAll(q).forEach(function(el){if(q==="p.cap"&&!/Sources?:|Data:|Source /.test(el.textContent))return;el.classList.add("md-src-only")})})}'
        'function set(v){on=v;document.body.classList.toggle("md-src",on);var b=document.getElementById("mdSrc");if(b){b.setAttribute("aria-pressed",String(on));b.textContent=on?"Hide sources":"Show sources"}try{localStorage.setItem("md-src",on?"1":"0")}catch(e){}}'
        'function init(){tag();set(on);document.getElementById("mdSrc").addEventListener("click",function(){set(!on)});new MutationObserver(function(){tag()}).observe(document.body,{childList:true,subtree:true})}'
        'if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();</script>')%json.dumps(HIDE[cur])
    return css+'<div class="mdnav"><a class="home" href="%s">← Market Desk</a><div class="r"><nav aria-label="Dashboards">%s</nav><a class="reg" href="%s"%s>Regimes</a><button type="button" id="mdSrc" aria-pressed="false">Show sources</button><a class="chat" href="https://claude.ai/code/session_01BrvMcoPQpxWG33kTPzFZ31" target="_blank" rel="noopener" title="Back to the Claude chat that builds Market Desk (only you can open it)">Open chat ↗</a></div></div>'%(links['home'],nav,links['regimes'],' aria-current="page" style="color:#fff;opacity:1;font-weight:600"' if cur=='regimes' else '')+js

COLL = {'etf': [['#history', 'Event archive'], ['#holdings', 'Check your own holdings']]}
def collapse_js(cur):
    if cur not in COLL: return ''
    return ('<style>.mdc-btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:6px;margin-top:6px;font:600 13px/1.2 "IBM Plex Sans",system-ui,sans-serif;color:#2947c8;border:1px solid #c8ced9;border-radius:999px;padding:4px 12px;background:#fff}.mdc-btn:focus-visible{outline:2px solid #2947c8;outline-offset:2px}.mdc-body[hidden]{display:none!important}</style>'
            '<script>(function(){var C=%s;function go(){C.forEach(function(c){var sec=document.querySelector(c[0]);if(!sec||sec.dataset.mdc)return;sec.dataset.mdc="1";var kids=[].slice.call(sec.children),head=kids.find(function(k){return k.querySelector&&(k.matches("h2,.sh,.rch")||k.querySelector("h2"))});if(!head)return;var body=document.createElement("div");body.className="mdc-body";body.hidden=true;kids.slice(kids.indexOf(head)+1).forEach(function(k){body.appendChild(k)});var b=document.createElement("button");b.type="button";b.className="mdc-btn";b.setAttribute("aria-expanded","false");b.textContent="Show "+c[1].toLowerCase()+" \\u25be";b.addEventListener("click",function(){body.hidden=!body.hidden;b.setAttribute("aria-expanded",String(!body.hidden));b.textContent=(body.hidden?"Show ":"Hide ")+c[1].toLowerCase()+(body.hidden?" \\u25be":" \\u25b4")});head.appendChild(b);sec.appendChild(body)})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",go);else go()})();</script>')%json.dumps(COLL[cur])
